    private List<String> board = new ArrayList<>();

    public List<List<String>> solveNQueens(int n) {
        this.n = n;
        cols = new boolean[n];
        d1 = new boolean[2 * n];
        d2 = new boolean[2 * n];
        dfs(0);
        return res;
    }

    private void dfs(int r) {
        if (r == n) {
            res.add(new ArrayList<>(board));
            return;
        }
        for (int c = 0; c < n; c++) {
            if (cols[c] || d1[r - c + n] || d2[r + c]) continue;
            cols[c] = true;
            d1[r - c + n] = true;
            d2[r + c] = true;
            char[] row = new char[n];
            Arrays.fill(row, '.');
            row[c] = 'Q';
            board.add(new String(row));
            dfs(r + 1);
            board.remove(board.size() - 1);
            cols[c] = false;
            d1[r - c + n] = false;
            d2[r + c] = false;
        }
    }
}

