import java.util.*;

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int[] a = nums1, b = nums2;
        if (a.length > b.length) {
            int[] t = a;
            a = b;
            b = t;
        }
        int m = a.length, n = b.length;
        int half = (m + n + 1) / 2;
        int l = 0, r = m;
        while (l <= r) {
            int i = (l + r) >>> 1, j = half - i;
            double la = i > 0 ? a[i - 1] : Double.NEGATIVE_INFINITY;
            double ra = i < m ? a[i] : Double.POSITIVE_INFINITY;
            double lb = j > 0 ? b[j - 1] : Double.NEGATIVE_INFINITY;
            double rb = j < n ? b[j] : Double.POSITIVE_INFINITY;
            if (la <= rb && lb <= ra) {
                if (((m + n) & 1) == 1) return Math.max(la, lb);
                return (Math.max(la, lb) + Math.min(ra, rb)) / 2.0;
            }
            if (la > rb) r = i - 1;
            else l = i + 1;
        }
        return 0.0;
    }
}

