class Solution {
    public boolean isValid(String s) {
        Map<Character, Character> pair = new HashMap<>();
        pair.put(')', '(');
        pair.put(']', '[');
        pair.put('}', '{');
        char[] st = new char[s.length()];
        int top = 0;
        for (char ch : s.toCharArray()) {
            if (pair.containsKey(ch)) {
                if (top == 0 || st[--top] != pair.get(ch)) return false;
            } else {
                st[top++] = ch;
            }
        }
        return top == 0;
    }
}

