class Solution {
    public String decodeString(String s) {
        Deque<String> strSt = new ArrayDeque<>();
        Deque<Integer> numSt = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        int k = 0;
        for (char ch : s.toCharArray()) {
            if (ch >= '0' && ch <= '9') {
                k = k * 10 + (ch - '0');
            } else if (ch == '[') {
                strSt.push(cur.toString());
                numSt.push(k);
                cur.setLength(0);
                k = 0;
            } else if (ch == ']') {
                String prev = strSt.pop();
                int num = numSt.pop();
                StringBuilder tmp = new StringBuilder(prev);
                for (int i = 0; i < num; i++) tmp.append(cur);
                cur = tmp;
            } else {
                cur.append(ch);
            }
        }
        return cur.toString();
    }
}

