import java.util.*;

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int[] hs = new int[n + 2];
        for (int i = 0; i < n; i++) hs[i + 1] = heights[i];
        int[] stack = new int[n + 2];
        int top = 0, best = 0;
        for (int i = 0; i < n + 2; i++) {
            while (top > 0 && hs[stack[top - 1]] > hs[i]) {
                int h = hs[stack[--top]];
                best = Math.max(best, h * (i - stack[top - 1] - 1));
            }
            stack[top++] = i;
        }
        return best;
    }
}

